using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table for nibble reversal: reverseBits(nibble)
    // e.g. 0b0001 -> 0b1000, 0b0011 -> 0b1100
    private static ReadOnlySpan<byte> NibbleLut => new byte[16]
    {
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    };

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static void ReverseInPlace(Span<byte> data)
    {
        int i = 0;
        int length = data.Length;
        ref byte ptr = ref MemoryMarshal.GetReference(data);

        if (Avx2.IsSupported && length >= 32)
        {
            // Use PSHUFB (VPSHUFB for 256-bit) to reverse bits via nibble lookup
            Vector256<byte> lowNibbleMask = Vector256.Create((byte)0x0F);
            Vector256<byte> lut = Vector256.Create(NibbleLut[0], NibbleLut[1], NibbleLut[2], NibbleLut[3],
                NibbleLut[4], NibbleLut[5], NibbleLut[6], NibbleLut[7],
                NibbleLut[8], NibbleLut[9], NibbleLut[10], NibbleLut[11],
                NibbleLut[12], NibbleLut[13], NibbleLut[14], NibbleLut[15],
                NibbleLut[0], NibbleLut[1], NibbleLut[2], NibbleLut[3],
                NibbleLut[4], NibbleLut[5], NibbleLut[6], NibbleLut[7],
                NibbleLut[8], NibbleLut[9], NibbleLut[10], NibbleLut[11],
                NibbleLut[12], NibbleLut[13], NibbleLut[14], NibbleLut[15]);

            for (; i + 32 <= length; i += 32)
            {
                Vector256<byte> vec = Vector256.LoadUnsafe(ref Unsafe.Add(ref ptr, i));
                // Split into low and high nibbles
                Vector256<byte> lo = Avx2.And(vec, lowNibbleMask);
                Vector256<byte> hi = Avx2.And(Avx2.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), lowNibbleMask);
