                Vector256<byte> reversedLo = Avx2.Shuffle(lut, lo);
                Vector256<byte> reversedHi = Avx2.Shuffle(lut, hi);
                Vector256<byte> result = Avx2.Or(Avx2.ShiftLeftLogical(reversedLo.AsUInt16(), 4).AsByte(), reversedHi);
