                Vector128<byte> lo = Sse2.And(vec, lowNibbleMask);
                Vector128<byte> hi = Sse2.And(Sse2.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), lowNibbleMask);
                Vector128<byte> reversedLo = Ssse3.Shuffle(lut, lo);
                Vector128<byte> reversedHi = Ssse3.Shuffle(lut, hi);
                Vector128<byte> result = Sse2.Or(Sse2.ShiftLeftLogical(reversedLo.AsUInt16(), 4).AsByte(), reversedHi);
                result.StoreUnsafe(ref Unsafe.Add(ref ptr, i));
            }
        }
        else if (AdvSimd.IsSupported && length >= 16)
        {
            // ARM NEON path using VTBL/vector lookup
            Vector128<byte> lowNibbleMask = Vector128.Create((byte)0x0F);
            Vector128<byte> lut = Vector128.Create(NibbleLut[0], NibbleLut[1], NibbleLut[2], NibbleLut[3],
                NibbleLut[4], NibbleLut[5], NibbleLut[6], NibbleLut[7],
                NibbleLut[8], NibbleLut[9], NibbleLut[10], NibbleLut[11],
                NibbleLut[12], NibbleLut[13], NibbleLut[14], NibbleLut[15]);
            Vector128<byte> four = Vector128.Create((byte)4);

            for (; i + 16 <= length; i += 16)
            {
                Vector128<byte> vec = Vector128.LoadUnsafe(ref Unsafe.Add(ref ptr, i));
                Vector128<byte> lo = AdvSimd.And(vec, lowNibbleMask);
                Vector128<byte> hi = AdvSimd.ShiftRightLogical(vec, four);
                hi = AdvSimd.And(hi, lowNibbleMask);
